const themeButton=document.querySelector('.theme');
let savedTheme;try{savedTheme=localStorage.getItem('kz-theme')}catch{}
if(savedTheme==='light')document.body.classList.add('light');
function updateThemeLabel(){themeButton.setAttribute('aria-label',document.body.classList.contains('light')?'Switch to dark theme':'Switch to light theme')}
updateThemeLabel();themeButton.addEventListener('click',()=>{document.body.classList.toggle('light');updateThemeLabel();try{localStorage.setItem('kz-theme',document.body.classList.contains('light')?'light':'dark')}catch{}});
const answers={study:"I'm a University of Connecticut student majoring in Analytics and Information Management.",aim:"AIM stands for Analytics and Information Management. It connects data analysis, information systems, and business decision-making.",about:"I'm Kellen Zumhofe, a student at the University of Connecticut studying Analytics and Information Management. Welcome to my portfolio!",projects:"My featured project is Fieldwork, a personal jersey collection archive with search, filters, photo uploads, collection editing, and export. Explore it in the Projects section below.",contact:"Contact details haven't been added to this portfolio yet.",fallback:"I can share Kellen's university and major, or explain Analytics and Information Management. Try asking ‘What are you studying?’"};
function reply(question){const q=question.toLowerCase();let a=answers.fallback;if(/aim|what is|analytics|information management/.test(q))a=answers.aim;else if(/stud|university|college|school|major|uconn|education/.test(q))a=answers.study;else if(/about|yourself|who|name|hello|hi\b/.test(q))a=answers.about;else if(/project|work|experience|resume|skill/.test(q))a=answers.projects;else if(/contact|email|linkedin|github|hire/.test(q))a=answers.contact;const log=document.getElementById('conversation');const user=document.createElement('p');user.className='system';user.textContent='› '+question;const answer=document.createElement('p');answer.className='answer';answer.textContent=a;log.append(user,answer);log.scrollTop=log.scrollHeight}
document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>reply(b.dataset.question)));
document.getElementById('ask-form').addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('question');const question=input.value.trim();if(question){reply(question);input.value=''}});
const sections=document.querySelectorAll('main section[id]');if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}})},{rootMargin:'-15% 0px -55% 0px'});sections.forEach(s=>observer.observe(s))}
document.getElementById('year').textContent=new Date().getFullYear();
